(function(root){
const P=root.Planner||(typeof require==='function'?require('./planner.js'):null);
const clone=x=>JSON.parse(JSON.stringify(x));
function adjust(blocks,id,patch,ripple=false){
 let before=clone(blocks),next=clone(blocks),event=next.find(b=>b.id===id);if(!event)return{ok:false,error:'That block no longer exists.'};if(event.type==='fixed')return{ok:false,error:'This commitment is fixed. Use Edit to change its time.'};
 Object.assign(event,patch);let start=P.mins(event.start);if(start===null||!Number.isFinite(event.duration)||(event.duration<15&&event.duration!==before.find(b=>b.id===id).duration)||start+event.duration>1440)return{ok:false,error:'Choose a time within this day and a duration of at least 15 minutes.'};
 if(ripple){let fixed=next.filter(b=>b.type==='fixed');if(fixed.some(b=>start<P.mins(b.start)+b.duration&&start+event.duration>P.mins(b.start)))return{ok:false,error:'That time overlaps a fixed commitment. Choose another time.'};let placed=[...fixed,event];let flexible=next.filter(b=>b.id!==id&&b.type!=='fixed').sort((a,b)=>P.mins(a.start)-P.mins(b.start));for(let b of flexible){let t=P.mins(b.start),conflict=true;while(conflict){conflict=false;for(let held of placed){let h=P.mins(held.start);if(t<h+held.duration&&t+b.duration>h){t=h+held.duration;conflict=true;break}}}if(t+b.duration>1440)return{ok:false,error:'These changes would push a block past midnight. Shorten it or choose another time.'};b.start=P.time(t);placed.push(b)}next=placed;}
 let errors=P.conflicts(next);if(errors.length)return{ok:false,error:errors[0]+'. Choose a free time.'};next.sort((a,b)=>P.mins(a.start)-P.mins(b.start));let changes=next.filter(b=>{let a=before.find(x=>x.id===b.id);return a.start!==b.start||a.duration!==b.duration||a.title!==b.title});return{ok:true,blocks:next,changes};
}
const nums={zero:0,one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,eleven:11,twelve:12,thirteen:13,fourteen:14,fifteen:15,sixteen:16,seventeen:17,eighteen:18,nineteen:19,twenty:20,thirty:30,forty:40,fifty:50,sixty:60,ninety:90};
function words(s){return s.toLowerCase().replace(/\b(twenty|thirty|forty|fifty)[ -](one|two|three|four|five|six|seven|eight|nine)\b/g,(_,a,b)=>String(nums[a]+nums[b])).replace(/\b(?:zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|ninety)\b/g,x=>String(nums[x])).replace(/\ba\s*\.?m\.?\b/g,'am').replace(/\bp\s*\.?m\.?\b/g,'pm')}
function parseTime(raw){let s=words(raw).trim().replace(/[.,]$/,'');if(s==='noon')return '12:00';if(s==='midnight')return '00:00';let m=s.match(/^(\d{1,2})(?::|\s+)?(\d{2})?\s*(am|pm)?$/);if(!m)return null;let h=+m[1],n=+(m[2]||0);if(n>59)return null;if(m[3]){if(h<1||h>12)return null;h=h%12+(m[3]==='pm'?12:0)}else if(h<0||h>23)return null;else if(h<=12&&!/^0\d:/.test(s)&&!/^1[0-2]:/.test(s))return null;return P.time(h*60+n)}
function findBlock(blocks,name){let norm=s=>s.toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim(),n=norm(name),all=blocks.filter(b=>norm(b.title)===n);if(!all.length)all=blocks.filter(b=>norm(b.title).startsWith(n));if(!all.length)all=blocks.filter(b=>norm(b.title).includes(n));return all.length===1?{block:all[0]}:{error:all.length?'More than one block matches “'+name+'”. Choose it below.':'No block matches “'+name+'”. Choose it below.'}}
function feedback(blocks,text,ripple=true){
 let parts=text.split(/;|\n|\bthen\b/i).map(x=>x.trim().replace(/[.!]$/,'')).filter(Boolean),next=clone(blocks),changes=[];if(!parts.length)return{ok:false,error:'Describe a change or use the controls below.'};
 for(let raw of parts){let m=raw.match(/^(?:move|schedule|put)\s+(.+?)\s+(?:to|at)\s+(.+)$/i),name,patch;if(m){name=m[1];let at=parseTime(m[2]);if(!at)return{ok:false,error:'Use a clear time such as “7 pm” or “19:00”.'};patch={start:at}}else{m=words(raw).match(/^(?:make|set|shorten|extend)\s+(.+?)\s+(?:to\s+)?(\d+)\s*(minutes?|mins?|hours?|hrs?)$/i);if(!m)return{ok:false,error:'I could not reliably read that request. Try “Move dinner to 7 pm” or “Make walk 30 minutes”, or use the controls below.'};name=m[1];patch={duration:+m[2]*(/^h/.test(m[3])?60:1)}}let found=findBlock(next,name);if(found.error)return{ok:false,error:found.error};let r=adjust(next,found.block.id,patch,ripple);if(!r.ok)return r;next=r.blocks;changes.push(...r.changes)}return{ok:true,blocks:next,changes:[...new Map(changes.map(b=>[b.id,b])).values()]};
}
root.CalendarModel={adjust,parseTime,feedback};if(typeof module!=='undefined')module.exports=root.CalendarModel;
})(typeof window!=='undefined'?window:globalThis);
